// decodeJSON decodes the members of an object whose opening brace has
// been read. path is the object's dotted path.
func (s *lowShadow) decodeJSON(dec *jsontext.Decoder, path string) error {
	for {
		tok, err := dec.ReadToken()
		if err != nil {
			return err
		}
		if tok.Kind() == jsontext.KindEndObject {
			return nil
		}
		switch key := tok.String(); key {
		case "max-in-flight":
			v, err := dec.ReadToken()
			if err != nil {
				return err
			}
			switch v.Kind() {
			case jsontext.KindNull:
			case jsontext.KindNumber:
				raw, err := v.Uint()
				if err != nil {
					return configJSONError(path+".max-in-flight", v, err)
				}
				if raw > math.MaxUint {
					return configJSONError(path+".max-in-flight", v, fmt.Errorf("%d overflows uint", raw))
				}
				num := uint(raw)
				s.MaxInFlight = &num
			default:
				return configJSONError(path+".max-in-flight", v, fmt.Errorf("expected a number, got %v", v.Kind()))
			}
		case "idle-grace":
			v, err := dec.ReadToken()
			if err != nil {
				return err
			}
			switch v.Kind() {
			case jsontext.KindNull:
			case jsontext.KindString:
				var slot impl.Duration
				if err := slot.UnmarshalText([]byte(v.String())); err != nil {
					return configJSONError(path+".idle-grace", v, err)
				}
				s.IdleGrace = &slot
			default:
				return configJSONError(path+".idle-grace", v, fmt.Errorf("expected a text scalar (e.g. \"30s\"), got %v", v.Kind()))
			}
		case "max-wait":
			v, err := dec.ReadToken()
			if err != nil {
				return err
			}
			switch v.Kind() {
			case jsontext.KindNull:
			case jsontext.KindString:
				var slot impl.Duration
				if err := slot.UnmarshalText([]byte(v.String())); err != nil {
					return configJSONError(path+".max-wait", v, err)
				}
				s.MaxWait = &slot
			default:
				return configJSONError(path+".max-wait", v, fmt.Errorf("expected a text scalar (e.g. \"30s\"), got %v", v.Kind()))
			}
		default:
			if reject, _ := json.GetOption(dec.Options(), json.RejectUnknownMembers); reject {
				return &configulator.UnknownKeyError{Path: path + "." + configQuoteKey(key)}
			}
			if err := dec.SkipValue(); err != nil {
				return err
			}
		}
	}
}

// configJSONError returns a ParseError for the JSON token v at path.
func configJSONError(path string, v jsontext.Token, err error) error {
	return &configulator.ParseError{
		Err:   err,
		Path:  path,
		Value: v.String(),
	}
}

// PrintConfig renders every field as "path = value" lines, redacting
// fields tagged secret:"true". The origin Report holds no values,
// so this is the only place redaction happens.
func (c Config) PrintConfig() string {
	var b strings.Builder
	fmt.Fprintf(&b, "log-level = %v\n", c.LogLevel)
	fmt.Fprintf(&b, "http.bind = %v\n", c.HTTP.Bind)
	fmt.Fprintf(&b, "http.port = %v\n", c.HTTP.Port)
	fmt.Fprintf(&b, "metrics.enabled = %v\n", c.Metrics.Enabled)
	fmt.Fprintf(&b, "metrics.bind = %v\n", c.Metrics.Bind)
	fmt.Fprintf(&b, "metrics.port = %v\n", c.Metrics.Port)
	fmt.Fprintf(&b, "upstream.url = %v\n", c.Upstream.URL)
	fmt.Fprintf(&b, "low.max-in-flight = %v\n", c.Low.MaxInFlight)
	fmt.Fprintf(&b, "low.idle-grace = %v\n", c.Low.IdleGrace)
	fmt.Fprintf(&b, "low.max-wait = %v\n", c.Low.MaxWait)
	fmt.Fprintf(&b, "generation-paths = %v\n", c.GenerationPaths)
	return b.String()
}

func configQuoteKey(k string) string {
	if strings.ContainsAny(k, ".[") {
		return "\"" + strings.NewReplacer("\\", "\\\\", "\"", "\\\"").Replace(k) + "\""
	}
	return k
}
